CALL apply_patch {"id":"c2","file_path":"data/blueprints/mbpp_940/solution.py","find":"# Write your function here.
","replace":"def heap_sort(array):
  build_max_heap(array)
  for i in range(len(array)-1, 0, -1):
    array[i], array[0] = array[0], array[i]
    heapify(array, i, 0)
  return array
def build_max_heap(array):
  length = len(array)
  start = length // 2 - 1
  for i in range(start, -1, -1):
    heapify(array, length, i)
def heapify(array, length, i):
  left_child = 2 * i + 1
  right_child = 2 * i + 2
  largest = i
  if left_child < length and array[left_child] > array[largest]:
    largest = left_child
  if right_child < length and array[right_child] > array[largest]:
    largest = right_child
  if largest != i:
    array[i], array[largest] = array[largest], array[i]
    heapify(array, length, largest)
"}

